<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/bootstrap.php'; require_once __DIR__ . '/../app/read_queries.php';
$sections=['entregas'=>['Entregas','ENTREGAS_VER'],'incidencias'=>['Incidencias','INCIDENCIAS_VER'],'notificaciones'=>['Notificaciones','NOTIFICACIONES_VER'],'documentos'=>['Documentos','DOCUMENTOS_VER']];$section=(string)($_GET['seccion']??'entregas');if(!isset($sections[$section])){$section='entregas';}require_permission($sections[$section][1]);require_once __DIR__.'/../app/layout.php';layout_start('entregas',$sections[$section][0],$section==='entregas'?'Consulta resultados de entrega y receptor efectivo.':'Consulta información asociada sin ejecutar acciones de registro.');
?>
<section class="panel-white"><nav class="module-tabs" aria-label="Secciones de entregas"><?php foreach($sections as $key=>[$label,$permission]):if(has_permission($permission)):?><a class="<?= $section===$key?'active':'' ?>" href="/entregas.php?seccion=<?= e($key) ?>"><?= e($label) ?></a><?php endif;endforeach;?></nav><div class="panel-heading-custom"><div><h2 class="title is-5"><?= e($sections[$section][0]) ?></h2><p><?= $section==='notificaciones'?'Historial de intentos. Esta pantalla no envía ni reintenta mensajes.':($section==='documentos'?'Consulta documentos por identificador de solicitud.':'Consulta de sólo lectura según permisos individuales.') ?></p></div><?php if($section==='incidencias'&&has_permission('INCIDENCIAS_REGISTRAR')):?><button class="button is-primary" hx-get="/entregas/incidencia_form.php?accion=registrar" hx-target="#modal-contenido"><?= svg_icon('plus') ?><span>Nueva incidencia</span></button><?php elseif($section==='documentos'&&has_permission('DOCUMENTOS_REGISTRAR')):?><button class="button is-primary" hx-get="/entregas/documento_form.php" hx-target="#modal-contenido"><?= svg_icon('plus') ?><span>Nuevo documento</span></button><?php endif;?></div>
<form class="filter-grid" id="entregas-filtros" hx-get="/entregas/lista.php" hx-target="#entregas-resultado" hx-trigger="change, keyup changed delay:350ms from:input" hx-include="this"><input type="hidden" name="seccion" value="<?= e($section) ?>"><?php if($section==='documentos'):?><div class="field mb-0"><label class="label" for="documentos-solicitud">Solicitud</label><div class="control"><input class="input" id="documentos-solicitud" name="solicitud_id" type="number" min="1" placeholder="ID de solicitud"></div></div><?php elseif($section==='incidencias'):?><div class="field mb-0"><label class="label" for="incidencias-estado">Estado</label><div class="control select is-fullwidth"><select id="incidencias-estado" name="estado"><option value="">Todos</option><option>ABIERTA</option><option>EN_ATENCION</option><option>RESUELTA</option></select></div></div><?php else:?><div class="field mb-0"><label class="label" for="entregas-estado">Estado</label><div class="control select is-fullwidth"><select id="entregas-estado" name="estado"><option value="">Todos</option><?php if($section==='entregas'):?><option>ENTREGADA</option><option>FALLIDA</option><?php else:?><option>PENDIENTE</option><option>ENVIADA</option><option>ERROR</option><?php endif;?></select></div></div><?php endif;?></form><div id="entregas-resultado" hx-get="/entregas/lista.php?seccion=<?= e($section) ?>" hx-trigger="load"><div class="is-skeleton" aria-label="Cargando resultados"></div></div></section><?php layout_end(); ?>
